import{_ as n,o as e,c as r,ag as o}from"./chunks/framework.BpFM782D.js";const c=JSON.parse('{"title":"frontend-design","description":"","frontmatter":{},"headers":[],"relativePath":"skills/frontend-design.md","filePath":"skills/frontend-design.md"}'),i={name:"skills/frontend-design.md"};function l(s,t,a,d,g,p){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="frontend-design" tabindex="-1">frontend-design <a class="header-anchor" href="#frontend-design" aria-label="Permalink to &quot;frontend-design&quot;">​</a></h1><table tabindex="0"><thead><tr><th>欄位</th><th>值</th></tr></thead><tbody><tr><td>名稱</td><td>frontend-design</td></tr><tr><td>說明</td><td>前端設計指南。UI/UX 設計原則、元件庫整合與設計系統。</td></tr><tr><td>來源目錄</td><td><code>skills/frontend-design/</code></td></tr></tbody></table><hr><p>此 skill 引導建立具有鮮明個性、達到生產品質的前端介面，避免泛用的「AI 罐頭」風格。實作真正可運行的程式碼，並對美學細節與創意選擇保持極致的用心。</p><p>使用者提供前端需求：要建立的元件、頁面、應用程式或介面。他們可能會附上目的、受眾或技術限制的說明。</p><h2 id="設計思維" tabindex="-1">設計思維 <a class="header-anchor" href="#設計思維" aria-label="Permalink to &quot;設計思維&quot;">​</a></h2><p>開始撰寫程式碼前，先理解情境，並確立一個大膽的美學方向：</p><ul><li><strong>目的</strong>：這個介面解決什麼問題？誰在使用它？</li><li><strong>基調</strong>：選定一個極端：極致簡約、最大主義混亂、復古未來感、有機/自然、奢華/精緻、俏皮/玩具感、編輯/雜誌風、粗野主義/原生、裝飾藝術/幾何、柔和/粉彩、工業/實用主義等。風格選擇千變萬化，以這些作為靈感，設計出真正忠於美學方向的作品。</li><li><strong>限制</strong>：技術需求（框架、效能、無障礙）。</li><li><strong>差異化</strong>：是什麼讓這個介面令人<strong>難以忘懷</strong>？人們會記住的那一件事是什麼？</li></ul><p><strong>重要</strong>：選定清晰的概念方向並精確執行。大膽的最大主義與精緻的極簡主義都能奏效——關鍵在於意圖，而非強度。</p><p>然後實作可運行的程式碼（HTML/CSS/JS、React、Vue 等），要求：</p><ul><li>達到生產等級且功能完整</li><li>視覺震撼且令人難忘</li><li>具有清晰美學觀點的一致風格</li><li>每個細節都經過精心雕琢</li></ul><h2 id="前端美學設計指南" tabindex="-1">前端美學設計指南 <a class="header-anchor" href="#前端美學設計指南" aria-label="Permalink to &quot;前端美學設計指南&quot;">​</a></h2><p>重點關注：</p><ul><li><strong>字型</strong>：選擇美觀、獨特且有趣的字型。避免 Arial、Inter 等泛用字型，改用能提升美感的獨特選擇；出人意料、有個性的字型搭配。配對一款有特色的展示字型與一款精緻的內文字型。</li><li><strong>色彩與主題</strong>：確立一致的美學風格。使用 CSS 變數保持一致性。主色調搭配銳利的強調色，效果優於膽怯、均勻分布的色板。</li><li><strong>動態效果</strong>：使用動畫製造視覺效果與微互動。HTML 優先考慮純 CSS 方案。React 中如有 Motion 函式庫則優先使用。聚焦於高衝擊力的時刻：一個精心編排的頁面載入搭配錯落的出現動畫（animation-delay），比散落各處的微互動更令人愉悅。善用捲動觸發與帶來驚喜的 hover 狀態。</li><li><strong>空間構圖</strong>：出人意料的版面配置。不對稱。重疊。斜向流動。打破網格的元素。慷慨的負空間，或有節制的高密度。</li><li><strong>背景與視覺細節</strong>：營造氛圍與深度，而非預設純色背景。加入與整體美學相符的情境效果與紋理。運用漸層網格、雜訊紋理、幾何圖案、層疊透明度、戲劇性陰影、裝飾性邊框、自訂游標、顆粒疊加等創意形式。</li></ul><p>絕對不要使用泛用的 AI 生成風格，包括：過度使用的字型系列（Inter、Roboto、Arial、系統字型）、老套的配色方案（尤其是白底紫色漸層）、可預測的版面與元件模式，以及缺乏情境特色的千篇一律設計。</p><p>發揮創意解讀，做出真正為情境而設計的意外選擇。每個設計都應該是獨一無二的。在淺色與深色主題、不同字型、不同美學之間切換。絕不在多次生成間收斂到常見選擇（例如 Space Grotesk）。</p><p><strong>重要</strong>：讓實作複雜度與美學願景相匹配。最大主義設計需要複雜的程式碼、大量動畫與效果。極簡或精緻設計需要克制、精確，以及對間距、字型與細微細節的用心。優雅來自於對願景的精良執行。</p><p>記住：Claude 有能力創作出非凡的作品。不要有所保留，展示在突破框架、全力投入獨特願景時真正能創造的東西。</p>',18)])])}const f=n(i,[["render",l]]);export{c as __pageData,f as default};
